CREATE TABLE IF NOT EXISTS rc_lease(slot INTEGER PRIMARY KEY,token TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL,started_at INTEGER,dispatch_at INTEGER,dispatch_ms INTEGER,finished_at INTEGER,owner TEXT,attempts INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS rc_latest(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,slot INTEGER NOT NULL,token TEXT NOT NULL,generated_at TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_samples(check_id TEXT NOT NULL,checked_at TEXT NOT NULL,status TEXT NOT NULL,latency_ms INTEGER,PRIMARY KEY(check_id,checked_at));
CREATE INDEX IF NOT EXISTS rc_samples_time ON rc_samples(checked_at);
CREATE TABLE IF NOT EXISTS rc_history(revision TEXT PRIMARY KEY,epoch INTEGER NOT NULL,source_rev INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_history_lock(revision TEXT PRIMARY KEY,token TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_manual_gate(id INTEGER PRIMARY KEY CHECK(id=1),last_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_daily_budget(day INTEGER PRIMARY KEY,api INTEGER NOT NULL,launch INTEGER NOT NULL,reads INTEGER NOT NULL,writes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_oidc_used(jti TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_oidc_diag(day INTEGER NOT NULL,at INTEGER NOT NULL,ray TEXT NOT NULL,steps TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS rc_oidc_diag_day ON rc_oidc_diag(day);
CREATE TABLE IF NOT EXISTS rc_oidc_probe(id INTEGER PRIMARY KEY CHECK(id=1),state TEXT NOT NULL,expires INTEGER NOT NULL,result TEXT);
